"""Página visual para anotar e treinar o reconhecimento de componentes."""


def component_trainer_html():
    return r"""<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Treinar reconhecimento de componentes</title>
<style>
:root{--blue:#1769aa;--ink:#17202a;--line:#d5dde5;--paper:#fff;--bg:#f3f5f7;--warn:#b45309;--bad:#b00020;--ok:#087a2f}
*{box-sizing:border-box}body{font-family:Arial,sans-serif;margin:0;background:var(--bg);color:var(--ink)}header{padding:16px 20px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:16px;flex-wrap:wrap}header h1{font-size:22px;margin:0}a{color:var(--blue)}main{padding:16px;display:grid;grid-template-columns:minmax(250px,320px) minmax(460px,1fr) minmax(280px,350px);gap:14px}.card{background:var(--paper);border:1px solid var(--line);border-radius:9px;padding:13px}.card h2{font-size:17px;margin:0 0 10px}.card h3{font-size:15px;margin:15px 0 7px}.muted{font-size:13px;color:#586875;line-height:1.4}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:8px 0}button,.button{border:0;border-radius:6px;padding:9px 11px;background:var(--blue);color:#fff;cursor:pointer;text-decoration:none;font-size:14px}button.secondary{background:#465a65}button.warn{background:var(--warn)}button.danger{background:var(--bad)}button:disabled{opacity:.55;cursor:not-allowed}input,select{width:100%;padding:8px;border:1px solid #b9c4ce;border-radius:5px;background:#fff}.small{width:90px}.image-list{max-height:235px;overflow:auto;border:1px solid var(--line);border-radius:6px}.image-item{padding:8px;border-bottom:1px solid #e6ebef;cursor:pointer;font-size:13px}.image-item.active{background:#dceeff}.source-box{border:1px solid var(--line);border-radius:7px;padding:9px;margin:8px 0}.source-box.cad{border-left:5px solid #7c3aed;background:#faf7ff}.source-box.hand{border-left:5px solid #1769aa}.badge{display:inline-block;padding:2px 6px;border-radius:10px;font-size:11px;font-weight:bold;margin-right:5px;background:#dbeafe;color:#174c83}.badge.cad{background:#ede9fe;color:#5b21b6}.canvas-wrap{position:relative;overflow:auto;min-height:500px;background:#252a30;border-radius:7px;display:flex;align-items:flex-start;justify-content:center}canvas{display:block;max-width:100%;height:auto;touch-action:none;cursor:crosshair}.toolbar{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:9px}.selected{outline:3px solid #ffb000}.stats{display:grid;grid-template-columns:1fr auto;gap:5px 10px;font-size:13px}.stats div{padding:3px 0;border-bottom:1px solid #edf0f2}.status{white-space:pre-wrap;font-size:13px;line-height:1.45;padding:9px;background:#f7f9fa;border:1px solid var(--line);border-radius:6px;max-height:260px;overflow:auto}.ok{color:var(--ok)}.bad{color:var(--bad)}.notice{border-left:4px solid var(--warn);padding:8px;background:#fff7ed;font-size:13px;line-height:1.4;margin:8px 0}.progress{height:12px;background:#dce3e8;border-radius:9px;overflow:hidden}.progress>div{height:100%;background:var(--blue);width:0}.kbd{font-family:monospace;background:#e9eef2;padding:1px 4px;border-radius:3px}@media(max-width:1100px){main{grid-template-columns:300px 1fr}.right{grid-column:1/-1}}@media(max-width:760px){main{display:block}.card{margin-bottom:12px}.canvas-wrap{min-height:360px}}
</style></head><body>
<header><a href="/workflow">← Voltar ao fluxo</a><h1>Treinar reconhecimento de componentes</h1><span class="muted">caixas e classes — não são os terminais</span></header>
<main>
<section class="card">
 <h2>1. Adicionar imagens</h2>
 <div class="source-box hand"><strong>Desenho feito à mão ou foto</strong><form id="uploadHandForm"><input id="uploadHandFile" name="file" type="file" accept="image/png,image/jpeg" required><input id="uploadHandName" name="name" placeholder="Nome do circuito (opcional)" style="margin-top:7px"><button style="margin-top:8px" type="submit">Adicionar circuito à mão</button></form></div>
 <div class="source-box cad"><strong>Adicionar circuito CAD</strong><p class="muted">Use exportações, capturas ou páginas de esquemas digitais em preto e branco.</p><form id="uploadCadForm"><input id="uploadCadFile" name="file" type="file" accept="image/png,image/jpeg" required><input id="uploadCadName" name="name" placeholder="Nome do circuito CAD (opcional)" style="margin-top:7px"><input id="uploadCadGroup" name="source_group" placeholder="Grupo/projeto CAD (opcional)" style="margin-top:7px"><button style="margin-top:8px" type="submit">Adicionar circuito CAD</button></form></div>
 <div id="uploadStatus" class="muted" style="margin:7px 0"></div><select id="sourceFilter"><option value="all">Todas as origens</option><option value="handwritten">Somente feitas à mão</option><option value="cad">Somente CAD</option></select>
 <div id="imageList" class="image-list">Carregando...</div>
 <h3>Classe da caixa</h3><select id="classSelect"></select>
 <div class="notice">Desenhe uma caixa justa ao redor de cada símbolo. Textos como R1, 10k e BC547 não devem ficar dentro da caixa se puderem ser evitados. Para ensinar fundos difíceis, adicione uma imagem sem componentes e salve com zero caixas: ela será usada como negativo real.</div>
 <h3>Contagem anotada</h3><div id="counts" class="stats"></div>
</section>

<section class="card">
 <h2>2. Corrigir caixas</h2>
 <div class="toolbar"><button id="drawBtn">Desenhar caixa</button><button id="selectBtn" class="secondary">Selecionar/mover</button><button id="deleteBtn" class="danger">Excluir selecionada</button><button id="saveBtn" class="warn">Salvar anotações</button></div>
 <p id="editorHint" class="muted">Escolha uma imagem. No modo desenho, arraste do canto superior esquerdo ao inferior direito. No modo seleção, arraste a caixa ou seus cantos.</p>
 <div id="canvasWrap" class="canvas-wrap"><canvas id="canvas"></canvas></div>
 <div class="row"><button id="prevBtn" class="secondary">← Anterior</button><button id="nextBtn" class="secondary">Próxima →</button><span id="boxInfo" class="muted"></span></div>
</section>

<aside class="card right">
 <h2>3. Preparar e treinar</h2>
 <p class="muted">O treino parte de uma base estável, usa recortes focados de cada componente, fundos reais como negativos difíceis e só ativa um peso que passar na validação.</p>
 <h3>Base sintética</h3><div class="row"><label>por classe <input id="perClass" class="small" type="number" min="10" max="1000" value="150"></label><button id="syntheticBtn" class="secondary">Gerar base</button></div>
 <h3>Dataset misto</h3><div class="row"><label>variações reais <input id="augments" class="small" type="number" min="0" max="10" value="2"></label><label>negativos de texto <input id="negatives" class="small" type="number" min="100" max="2000" value="450"></label></div><button id="mixedBtn">Montar dataset misto</button>
 <h3>Treinamento</h3><div class="row"><label>épocas <input id="epochs" class="small" type="number" min="1" max="500" value="80"></label><label>imagem <select id="imgsz" class="small"><option>320</option><option>416</option><option>512</option><option selected>640</option><option>768</option><option>960</option><option>1024</option></select></label></div><div class="row"><label>batch <input id="batch" class="small" type="number" min="1" max="128" value="8"></label><label>paciência <input id="patience" class="small" type="number" min="1" max="500" value="20"></label><label>dispositivo <select id="device" class="small"><option value="cpu">CPU</option><option value="0">GPU 0</option></select></label></div>
 <div class="row"><button id="trainBtn" class="warn">Iniciar treinamento</button><button id="stopBtn" class="danger" disabled>Finalizar após esta época e validar</button><button id="resumeBtn" class="secondary" disabled>Retomar treinamento interrompido</button><button id="rollbackBtn" class="danger">Restaurar modelo anterior</button><button id="foundationBtn" class="secondary">Fixar modelo atual como base estável</button></div>
 <div style="margin:11px 0" class="progress"><div id="progressBar"></div></div><div id="trainStatus" class="status">Consultando estado...</div>
 <h3>Diagnóstico objetivo</h3><p class="muted">Audita caixas grandes/duplicadas, classes desequilibradas e mede precision, recall e F1 em caneta preta, azul, vermelha e verde usando a validação real.</p><div class="row"><button id="quickAuditBtn" class="secondary">Auditar anotações</button><button id="fullAuditBtn">Testar modelo e cores</button></div><div id="auditStatus" class="status">Nenhuma auditoria executada.</div>
</aside>
</main>
<script>
const $=id=>document.getElementById(id), canvas=$('canvas'), ctx=canvas.getContext('2d');
let classes=[],allImages=[],images=[],current=null,img=new Image(),boxes=[],selected=-1,mode='draw',action=null,start=null,dirty=false;
const colors=['#00c2ff','#ff8c00','#7c4dff','#00a651','#e91e63','#795548','#f44336','#3f51b5','#009688','#607d8b','#ff5722','#8bc34a','#673ab7','#2196f3','#cddc39'];
async function api(url,opts={}){const r=await fetch(url,opts),d=await r.json();if(!r.ok)throw new Error(d.detail||d.message||'Erro');return d}
function className(id){const c=classes.find(x=>x.id===Number(id));return c?c.name:'classe '+id}
async function boot(){classes=await api('/real-dataset/classes');$('classSelect').innerHTML=classes.map(c=>`<option value="${c.id}">${c.id} — ${c.name}</option>`).join('');await reloadImages();await refreshInfo();await refreshTraining()}
async function reloadImages(selectId){allImages=await api('/real-dataset/images');const filter=$('sourceFilter').value;images=allImages.filter(r=>filter==='all'||r.source_type===filter);$('imageList').innerHTML=images.length?'':'Nenhuma imagem desta origem.';images.forEach((r,i)=>{const e=document.createElement('div');e.className='image-item'+(current&&current.image_id===r.image_id?' active':'');const badge=document.createElement('span');badge.className='badge '+(r.source_type==='cad'?'cad':'');badge.textContent=r.source_type==='cad'?'CAD':'À MÃO';const label=document.createElement('span');label.textContent=`${r.image_id} — ${r.name} (${r.annotation_count} caixas)`;e.append(badge,label);e.onclick=()=>choose(i);$('imageList').appendChild(e)});if(selectId){const i=images.findIndex(x=>x.image_id===selectId);if(i>=0)await choose(i)}}
async function choose(index){if(dirty&&!confirm('Há caixas não salvas. Deseja trocar de imagem mesmo assim?'))return;current=images[index];boxes=(current.annotations||[]).map(b=>({...b}));selected=-1;dirty=false;img.onload=()=>{canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;render()};img.src=current.image_url+'?t='+Date.now();await reloadImages();$('boxInfo').textContent=`${current.width}×${current.height} — ${boxes.length} caixa(s)`}
function render(){ctx.clearRect(0,0,canvas.width,canvas.height);if(img.complete)ctx.drawImage(img,0,0,canvas.width,canvas.height);boxes.forEach((b,i)=>{ctx.save();ctx.strokeStyle=colors[b.class_id%colors.length];ctx.lineWidth=Math.max(2,canvas.width/500);ctx.setLineDash(i===selected?[]:[7,4]);ctx.strokeRect(b.x1,b.y1,b.x2-b.x1,b.y2-b.y1);const label=className(b.class_id);ctx.font=`${Math.max(13,canvas.width/80)}px Arial`;const tw=ctx.measureText(label).width+8,th=Math.max(19,canvas.width/60);ctx.fillStyle=colors[b.class_id%colors.length];ctx.fillRect(b.x1,Math.max(0,b.y1-th),tw,th);ctx.fillStyle='#fff';ctx.fillText(label,b.x1+4,Math.max(14,b.y1-4));if(i===selected){ctx.fillStyle='#fff';ctx.strokeStyle='#111';for(const p of handles(b)){ctx.fillRect(p.x-6,p.y-6,12,12);ctx.strokeRect(p.x-6,p.y-6,12,12)}}ctx.restore()});if(action==='new'&&start&&start.preview){const b=start.preview;ctx.strokeStyle='#ffb000';ctx.lineWidth=3;ctx.strokeRect(b.x1,b.y1,b.x2-b.x1,b.y2-b.y1)}}
function point(ev){const r=canvas.getBoundingClientRect();return{x:(ev.clientX-r.left)*canvas.width/r.width,y:(ev.clientY-r.top)*canvas.height/r.height}}
function handles(b){return[{name:'nw',x:b.x1,y:b.y1},{name:'ne',x:b.x2,y:b.y1},{name:'sw',x:b.x1,y:b.y2},{name:'se',x:b.x2,y:b.y2}]}
function hit(p){for(let i=boxes.length-1;i>=0;i--){const b=boxes[i];for(const h of handles(b))if(Math.hypot(p.x-h.x,p.y-h.y)<14)return{i,handle:h.name};if(p.x>=b.x1&&p.x<=b.x2&&p.y>=b.y1&&p.y<=b.y2)return{i,handle:'move'}}return null}
canvas.onpointerdown=e=>{if(!current)return;canvas.setPointerCapture(e.pointerId);const p=point(e);if(mode==='draw'){action='new';start={x:p.x,y:p.y,preview:null}}else{const h=hit(p);selected=h?h.i:-1;if(h){action=h.handle;start={x:p.x,y:p.y,box:{...boxes[selected]}}}render()}};
canvas.onpointermove=e=>{if(!action||!start)return;const p=point(e);if(action==='new'){start.preview={x1:Math.min(start.x,p.x),y1:Math.min(start.y,p.y),x2:Math.max(start.x,p.x),y2:Math.max(start.y,p.y)}}else{let b={...start.box},dx=p.x-start.x,dy=p.y-start.y;if(action==='move'){const w=b.x2-b.x1,h=b.y2-b.y1;b.x1=Math.max(0,Math.min(canvas.width-w,b.x1+dx));b.y1=Math.max(0,Math.min(canvas.height-h,b.y1+dy));b.x2=b.x1+w;b.y2=b.y1+h}else{if(action.includes('n'))b.y1=Math.max(0,Math.min(b.y2-3,start.box.y1+dy));if(action.includes('s'))b.y2=Math.min(canvas.height,Math.max(b.y1+3,start.box.y2+dy));if(action.includes('w'))b.x1=Math.max(0,Math.min(b.x2-3,start.box.x1+dx));if(action.includes('e'))b.x2=Math.min(canvas.width,Math.max(b.x1+3,start.box.x2+dx))}boxes[selected]=b;dirty=true}render()};
canvas.onpointerup=()=>{if(action==='new'&&start.preview&&start.preview.x2-start.preview.x1>=3&&start.preview.y2-start.preview.y1>=3){boxes.push({...start.preview,class_id:Number($('classSelect').value)});selected=boxes.length-1;dirty=true}action=null;start=null;render();$('boxInfo').textContent=current?`${current.width}×${current.height} — ${boxes.length} caixa(s)`:''};
$('classSelect').onchange=()=>{if(selected>=0){boxes[selected].class_id=Number($('classSelect').value);dirty=true;render()}};
$('drawBtn').onclick=()=>{mode='draw';$('editorHint').textContent='Modo desenho: arraste para criar uma caixa.'};$('selectBtn').onclick=()=>{mode='select';$('editorHint').textContent='Modo seleção: clique e arraste a caixa para mover; use os quatro cantos para redimensionar.'};
$('deleteBtn').onclick=()=>{if(selected>=0){boxes.splice(selected,1);selected=-1;dirty=true;render()}};
$('saveBtn').onclick=async()=>{if(!current)return alert('Escolha uma imagem.');try{current=await api('/real-dataset/images/'+current.image_id+'/annotations',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({boxes})});dirty=false;await reloadImages(current.image_id);await refreshInfo();alert('Anotações salvas. Elas já estão disponíveis para montar o dataset.')}catch(e){alert(e.message)}};
async function uploadSource(formId,fileId,nameId,sourceType,groupId=''){const f=$(fileId).files[0];if(!f)return;const fd=new FormData();fd.append('file',f);fd.append('name',$(nameId).value);fd.append('source_type',sourceType);if(groupId)fd.append('source_group',$(groupId).value);$('uploadStatus').textContent='Enviando '+(sourceType==='cad'?'circuito CAD':'desenho feito à mão')+'...';try{const r=await api('/real-dataset/upload',{method:'POST',body:fd});$(formId).reset();$('sourceFilter').value=sourceType;$('uploadStatus').textContent=(sourceType==='cad'?'Circuito CAD':'Imagem feita à mão')+' adicionado(a). Agora marque todos os componentes.';await reloadImages(r.image_id);await refreshInfo()}catch(err){$('uploadStatus').textContent='Erro: '+err.message}}
$('uploadHandForm').onsubmit=e=>{e.preventDefault();uploadSource('uploadHandForm','uploadHandFile','uploadHandName','handwritten')};
$('uploadCadForm').onsubmit=e=>{e.preventDefault();uploadSource('uploadCadForm','uploadCadFile','uploadCadName','cad','uploadCadGroup')};
$('sourceFilter').onchange=()=>reloadImages();
$('prevBtn').onclick=()=>{if(!current||!images.length)return;choose((images.findIndex(x=>x.image_id===current.image_id)-1+images.length)%images.length)};$('nextBtn').onclick=()=>{if(!current||!images.length)return;choose((images.findIndex(x=>x.image_id===current.image_id)+1)%images.length)};
async function refreshInfo(){const d=await api('/real-dataset/info');$('counts').innerHTML=`<div><b>Imagens feitas à mão</b></div><div><b>${d.images_by_source?.handwritten||0}</b></div><div><b>Imagens CAD</b></div><div><b>${d.images_by_source?.cad||0}</b></div><div>Caixas feitas à mão</div><div>${d.boxes_by_source?.handwritten||0}</div><div>Caixas CAD</div><div>${d.boxes_by_source?.cad||0}</div>`+classes.map(c=>`<div>${c.name}</div><div>${d.boxes_by_class[c.key]||0}</div>`).join('')+`<div>Imagens negativas revisadas</div><div>${d.reviewed_negative_images||0}</div><div><b>Total de caixas</b></div><div><b>${d.boxes}</b></div>`}
async function runButton(button,fn){button.disabled=true;try{await fn()}catch(e){alert(e.message)}finally{button.disabled=false}}
$('syntheticBtn').onclick=()=>runButton($('syntheticBtn'),async()=>{const d=await api('/dataset/generate?per_class='+Number($('perClass').value),{method:'POST'});alert(d.mensagem)});
$('mixedBtn').onclick=()=>runButton($('mixedBtn'),async()=>{const q=new URLSearchParams({real_train_augments:$('augments').value,text_negative_count:$('negatives').value});const d=await api('/real-dataset/build-mixed?'+q,{method:'POST'});alert(d.mensagem);await refreshTraining()});
$('trainBtn').onclick=()=>runButton($('trainBtn'),async()=>{if(!confirm('Iniciar o treinamento IA-first? Ele usará a base estável, recortes focados e negativos reais. O modelo ativo só será trocado se a precisão for aprovada.'))return;const q=new URLSearchParams({epochs:$('epochs').value,imgsz:$('imgsz').value,batch:$('batch').value,patience:$('patience').value,device:$('device').value});const d=await api('/component-learning/train?'+q,{method:'POST'});$('trainStatus').textContent=d.message;await refreshTraining()});
$('stopBtn').onclick=()=>runButton($('stopBtn'),async()=>{if(!confirm('Finalizar ao término da época atual e validar o melhor checkpoint produzido até agora?'))return;const d=await api('/component-learning/stop-and-validate',{method:'POST'});$('trainStatus').textContent=d.message;await refreshTraining()});
$('resumeBtn').onclick=()=>runButton($('resumeBtn'),async()=>{if(!confirm('Continuar do último checkpoint salvo? Mantenha o servidor aberto até a conclusão.'))return;const d=await api('/component-learning/resume',{method:'POST'});$('trainStatus').textContent=d.message;await refreshTraining()});
$('rollbackBtn').onclick=()=>runButton($('rollbackBtn'),async()=>{if(!confirm('Restaurar o modelo que estava ativo antes do último treinamento? O modelo atual será guardado como rejeitado.'))return;const d=await api('/component-learning/rollback',{method:'POST'});alert(d.message);await refreshTraining()});
$('foundationBtn').onclick=()=>runButton($('foundationBtn'),async()=>{if(!confirm('Confirmar que o modelo ativo atual será a origem estável dos próximos treinamentos? Use isto depois de restaurar o modelo anterior.'))return;const d=await api('/component-learning/foundation-from-active',{method:'POST'});alert(d.message);await refreshTraining()});
$('quickAuditBtn').onclick=()=>runButton($('quickAuditBtn'),async()=>{const d=await api('/component-learning/dataset-audit');$('auditStatus').textContent=`Imagens: ${d.image_count}\nInstâncias: ${d.instance_count}\nProblemas de caixas: ${d.issue_count}\nPossíveis duplicadas: ${d.possible_duplicate_annotation_pairs}\nSobreposição entre classes: ${d.overlapping_different_class_pairs}\nDesequilíbrio maior/menor: ${d.class_imbalance_max_over_min??'n/d'}\n\nCorrija primeiro as imagens listadas no relatório completo quando houver problemas.`});
$('fullAuditBtn').onclick=()=>runButton($('fullAuditBtn'),async()=>{if(!confirm('Executar diagnóstico sobre até 60 imagens reais de validação e quatro cores de caneta? Pode levar alguns minutos na CPU.'))return;const d=await api('/component-learning/diagnostic?max_images=60&confidence=0.25&imgsz=640',{method:'POST'});$('auditStatus').textContent='Diagnóstico iniciado. Estado: '+d.state;await refreshDiagnostic()});
async function refreshDiagnostic(){try{const d=await api('/component-learning/diagnostic/status');$('fullAuditBtn').disabled=d.state==='running';let lines=[`Estado: ${d.state}`,d.message||''];const r=d.report||d.last_report;if(r?.dataset_audit)lines.push(`Labels: ${r.dataset_audit.issue_count} problema(s), ${r.dataset_audit.possible_duplicate_annotation_pairs} duplicidade(s), ${r.dataset_audit.overlapping_different_class_pairs} conflito(s) entre classes.`);if(r?.pen_color_evaluation){lines.push('Métricas por cor:');for(const [cor,m] of Object.entries(r.pen_color_evaluation.metrics_by_pen_color||{}))lines.push(`${cor}: precision=${m.precision} recall=${m.recall} F1=${m.f1} FP=${m.fp} FN=${m.fn}`);lines.push(`Variação de F1 entre cores: ${r.pen_color_evaluation.f1_spread_max_minus_min}`)}$('auditStatus').textContent=lines.filter(Boolean).join('\n')}catch(e){$('auditStatus').textContent='Erro no diagnóstico: '+e.message}}
async function refreshTraining(){try{const d=await api('/component-learning/status');const pct=d.progress_percent||0,busy=['running','stopping'].includes(d.state);$('progressBar').style.width=Math.min(100,pct)+'%';$('trainBtn').disabled=busy;$('stopBtn').disabled=d.state!=='running';$('resumeBtn').disabled=busy||!d.resume_available;$('rollbackBtn').disabled=busy;$('foundationBtn').disabled=busy;let lines=[`Estado: ${d.state}`,d.message||'',`Dataset misto: ${d.dataset_ready?'pronto':'ainda não gerado'}`,`Modelo ativo: ${d.model_exists?'encontrado':'não encontrado'}`,`Base estável: ${d.foundation_model_exists?'preservada':'será criada no próximo treino'}`];if(d.current_epoch)lines.push(`Época: ${d.current_epoch}/${d.epochs} (${pct}%)`);if(d.resume_available)lines.push('Checkpoint encontrado: pronto para retomar da última época salva.');if(d.backup_path)lines.push('Backup: '+d.backup_path);if(d.summary?.foundation_model)lines.push('Origem do treinamento: '+d.summary.foundation_model);if(d.summary?.mixed_validation)lines.push('Validação mista: '+JSON.stringify(d.summary.mixed_validation));if(d.summary?.real_only_validation)lines.push('Validação real: '+JSON.stringify(d.summary.real_only_validation));if(d.summary?.quality_gate)lines.push('Proteção de qualidade: '+(d.summary.quality_gate.passed?'APROVADO':'REJEITADO')+' '+JSON.stringify(d.summary.quality_gate.reasons||[]));$('trainStatus').textContent=lines.filter(Boolean).join('\n');$('trainStatus').className='status '+(['failed','rejected'].includes(d.state)?'bad':['completed','rolled_back','foundation_updated'].includes(d.state)?'ok':'')}catch(e){$('trainStatus').textContent='Erro ao consultar: '+e.message}}
setInterval(refreshTraining,2500);setInterval(refreshDiagnostic,3500);boot().then(refreshDiagnostic).catch(e=>alert('Falha ao abrir o treinador: '+e.message));
</script></body></html>"""
